css:
:root {
  --primary: #ff3cac;
  --primary-hover: #784ba0;
  --bg: #0f1024;
  --bg-alt: #1d1633;
  --text: #f9f5ff;
  --text-secondary: #c7b7ff;
  --card-bg: rgba(15, 16, 36, 0.8);
  --border: rgba(255, 255, 255, 0.12);
  --success: #2ce8a5;
  --warning: #f7c948;
  --error: #ff6b6b;
}

body {
  background: radial-gradient(circle at 20% 20%, rgba(255, 60, 172, 0.12) 0, transparent 40%),
              radial-gradient(circle at 80% 0%, rgba(124, 75, 160, 0.25) 0, transparent 35%),
              linear-gradient(145deg, #0f1024 0%, #1d1633 40%, #0f1024 100%);
  color: var(--text);
  letter-spacing: 0.02em;
  backdrop-filter: saturate(1.05);
}

.header {
  background: linear-gradient(120deg, rgba(255, 60, 172, 0.15), rgba(124, 75, 160, 0.25));
  border-bottom: 1px solid var(--border);
  box-shadow: 0 12px 30px rgba(255, 60, 172, 0.08);
}

.brand {
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  background: linear-gradient(90deg, #ff3cac, #784ba0, #2b86c5);
  background-clip: text;
  -webkit-background-clip: text;
  color: transparent;
  text-shadow: 0 0 12px rgba(255, 60, 172, 0.5);
}

.board {
  background: repeating-linear-gradient(
    90deg,
    rgba(255, 255, 255, 0.03) 0,
    rgba(255, 255, 255, 0.03) 1px,
    transparent 1px,
    transparent 60px
  ),
  linear-gradient(180deg, rgba(43, 134, 197, 0.05), rgba(15, 16, 36, 0.8));
}

.card {
  background: var(--card-bg);
  border: 1px solid var(--border);
  border-radius: 16px;
  box-shadow: 0 12px 38px rgba(43, 134, 197, 0.2);
  backdrop-filter: blur(8px) saturate(1.2);
  transform: translateZ(0);
  transition: transform 0.25s ease, box-shadow 0.25s ease, border-color 0.25s ease;
}

.card:hover {
  transform: translateY(-4px) scale(1.01);
  border-color: rgba(255, 60, 172, 0.6);
  box-shadow: 0 18px 46px rgba(255, 60, 172, 0.22);
}

.card .tag, .tag {
  background: linear-gradient(135deg, #2b86c5, #ff3cac);
  color: #0f1024;
  border: none;
  box-shadow: 0 10px 24px rgba(124, 75, 160, 0.3);
}

button, .button, .cta {
  background: linear-gradient(135deg, #ff3cac 0%, #2b86c5 100%);
  color: #0f1024;
  border: none;
  border-radius: 12px;
  box-shadow: 0 10px 28px rgba(255, 60, 172, 0.3);
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

button:hover, .button:hover, .cta:hover {
  transform: translateY(-2px);
  box-shadow: 0 14px 34px rgba(43, 134, 197, 0.4);
}

input, textarea {
  background: rgba(15, 16, 36, 0.7);
  border: 1px solid var(--border);
  color: var(--text);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.04);
}
